// ---- M-Room Approval: parse the request from Book M-Room and size the window ----
// The webhook body carries the shared-use request that overlapped a standing hold.
// All times are Philippine Standard Time (Asia/Manila, UTC+8).

// FILL THESE IN: the approvers' Slack member IDs (Uxxxxxxxx). Placeholders below.
const ROOMS = {
  M2: { holdOwner: 'Peemo Morato',            approverName: 'Peemo Morato', approverSlackId: '<<M2_APPROVER_SLACK_ID>>', resource: 'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com' },
  M6: { holdOwner: 'Marketing',            approverName: 'Nicole Miller', approverSlackId: '<<M6_APPROVER_SLACK_ID>>', resource: 'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com' },
  M7: { holdOwner: 'Business Development (BD)', approverName: 'Ana Cadelina', approverSlackId: '<<M7_APPROVER_SLACK_ID>>', resource: 'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com' }
};

const b = $input.first().json.body || $input.first().json;

const room = String(b.room || '').trim().toUpperCase();
const cfg = ROOMS[room];
if (!cfg) { throw new Error('M-Room Approval called for a room without a hold: ' + room); }

const ZONE = 'Asia/Manila';
const now = DateTime.now().setZone(ZONE);

const allDay = b.all_day === true || b.all_day === 'true';
// Booking start: for a timed booking use start_iso; for all-day use the start of the booking date.
const bookingDateIso = String(b.booking_date || b.start_iso || '').slice(0, 10);
const bookingStart = allDay
  ? DateTime.fromISO(bookingDateIso, { zone: ZONE }).startOf('day')
  : DateTime.fromISO(String(b.start_iso), { zone: ZONE });

if (!bookingStart.isValid) { throw new Error('Could not read the booking start from the request.'); }

// ---- Lead-time window (PST) ----
// same-day request        -> 1 hour
// requested the day before -> until 10:00 AM on the booking day
// requested 2+ days before -> 24 hours
const dReq  = now.startOf('day');
const dBook = bookingStart.startOf('day');
const daysAhead = Math.round(dBook.diff(dReq, 'days').days);

let deadline, category;
if (daysAhead <= 0) {
  category = 'same-day';
  deadline = now.plus({ hours: 1 });
} else if (daysAhead === 1) {
  category = 'day-before';
  deadline = dBook.set({ hour: 10, minute: 0, second: 0, millisecond: 0 });
} else {
  category = '2+ days';
  deadline = now.plus({ hours: 24 });
}

// Never wait past the session itself. For a timed booking, cap at the start time;
// for an all-day booking, cap at the end of the booking day.
const latest = allDay ? dBook.endOf('day') : bookingStart;
if (deadline > latest) { deadline = latest; }
// If the window has already effectively closed (booking is imminent/past), the
// approver still gets a heads-up but the wait resolves at the (near) deadline.
if (deadline < now) { deadline = now.plus({ minutes: 1 }); }

return [{ json: {
  room,
  holdOwner: cfg.holdOwner,
  approverName: cfg.approverName,
  approverSlackId: cfg.approverSlackId,
  resource: cfg.resource,
  requesterName: b.requester_name || 'the requester',
  requesterSlackId: b.requester_slack_id || '',
  title: b.summary || (room + ' - booking'),
  startIso: allDay ? bookingDateIso : String(b.start_iso),
  endIso: allDay ? DateTime.fromISO(bookingDateIso, { zone: ZONE }).plus({ days: 1 }).toISODate() : String(b.end_iso),
  allDay,
  bookingStartIso: bookingStart.toISO(),
  bookingDateHuman: bookingStart.toFormat('cccc, MMMM d, yyyy'),
  timeHuman: allDay ? 'All day' : (bookingStart.toFormat('h:mm a') + ' – ' + DateTime.fromISO(String(b.end_iso), { zone: ZONE }).toFormat('h:mm a')),
  description: b.description || '',
  bookerRef: b.requester_slack_id || '',
  category,
  deadlineIso: deadline.toISO(),
  deadlineHuman: deadline.toFormat('cccc, MMMM d, h:mm a')
} }];

// Read how the wait resumed. A click carries ?decision=approve|decline in the query;
// a time-limit resume carries no decision -> non-response -> BOOK (never blocks).
const w = $input.first().json || {};
const decision = String(
  (w.query && w.query.decision) ||
  (w.params && w.params.decision) ||
  (w.body && w.body.decision) ||
  w.decision || ''
).toLowerCase().trim();

let outcome, reason;
if (decision === 'decline' || decision === 'declined' || decision === 'no') {
  outcome = 'decline'; reason = 'declined';
} else if (decision === 'approve' || decision === 'approved' || decision === 'yes') {
  outcome = 'book'; reason = 'approved';
} else {
  outcome = 'book'; reason = 'no-response';
}

const c = $('Compute').item.json;
return [{ json: Object.assign({}, c, { outcome, reason }) }];

// Safety re-check before creating: has a NON-hold booking taken the room since the
// request came in, or has the start slipped into the past? The standing hold itself
// does NOT count as a conflict — approval (or non-response) is exactly permission to
// overlap it.
const c = $('Resolve Outcome').item.json;
const ZONE = 'Asia/Manila';
const room = c.room;

// Hold owner keywords per room, to tell the standing hold apart from a real booking.
const HOLD_KEYWORDS = { M2: ['peemo'], M6: ['marketing'], M7: ['bd', 'business development'] };
const holdWords = HOLD_KEYWORDS[room] || [];

const reqStart = DateTime.fromISO(c.bookingStartIso, { zone: ZONE });
const reqEnd = c.allDay
  ? DateTime.fromISO(c.startIso, { zone: ZONE }).plus({ days: 1 }).startOf('day')
  : DateTime.fromISO(c.endIso, { zone: ZONE });
const now = DateTime.now().setZone(ZONE);

if (reqStart < now.startOf('day')) {
  return [{ json: Object.assign({}, c, { slot: 'past' }) }];
}

const events = $input.all().map(i => i.json).filter(e => e && (e.summary || e.start));
let conflict = null;
for (const e of events) {
  const title = String(e.summary || '');
  // Only events for THIS room (internal-room titles start with the room name).
  if (!new RegExp('^' + room + '\\b', 'i').test(title.trim())) continue;
  // Skip the standing hold itself.
  const lower = title.toLowerCase();
  const isHold = holdWords.some(w => lower.includes(w));
  if (isHold) continue;
  // Overlap test.
  const es = e.start && (e.start.dateTime || e.start.date);
  const ee = e.end && (e.end.dateTime || e.end.date);
  if (!es || !ee) continue;
  const s = DateTime.fromISO(String(es), { zone: ZONE });
  const en = DateTime.fromISO(String(ee), { zone: ZONE });
  if (s < reqEnd && en > reqStart) { conflict = title; break; }
}

return [{ json: Object.assign({}, c, { slot: conflict ? 'taken' : 'ok', conflictTitle: conflict || '' }) }];
